class Admission:
    def __init__(self, app, limit: int, path: str = "/buy"):
        self.app, self.limit, self.path = app, limit, path
        self.inflight = 0
        self.shed = 0

    async def __call__(self, scope, receive, send):
        if not self.limit or scope["type"] != "http" or scope["path"] != self.path:
            return await self.app(scope, receive, send)
        if self.inflight >= self.limit:
            self.shed += 1
            await send({"type": "http.response.start", "status": 503, "headers": REJECT_HEADERS})
            await send({"type": "http.response.body", "body": REJECT_BODY})
            return
        self.inflight += 1
        try:
            await self.app(scope, receive, send)
        finally:
            self.inflight -= 1

