# nginx: load balancer in front of the seller instances (:8080, M8) and the
# client-calibration target (:8081, M3).
worker_processes auto;
worker_rlimit_nofile 65535;
events { worker_connections 16384; }

http {
    access_log off;
    keepalive_requests 100000;
    keepalive_timeout 75s;

    # Three identical, stateless sellers. They share nothing but Postgres: no
    # application-level lock, no sticky sessions. Every invariant is enforced by
    # Postgres constraints, so it does not matter which instance a request -- or
    # its duplicate, or its retry -- lands on.
    upstream sellers {
        # least_conn rather than round-robin: when the datastore slows down, the
        # instance stuck with slow requests gets fewer new ones.
        least_conn;
        server seller1:8000;
        server seller2:8000;
        server seller3:8000;
        # Reuse upstream connections; without this nginx opens a new TCP
        # connection to a seller for every request.
        keepalive 256;
    }

    server {
        listen 8080;
        location / {
            proxy_pass http://sellers;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            # Stated explicitly: nginx does NOT resend a POST to another seller
            # once it was sent (no `non_idempotent`). A connect failure (nothing
            # sent) may still try the next seller. The seller is idempotent on
            # request_id anyway, but a hidden retry inside the load balancer
            # would also hide failures from the measurements.
            proxy_next_upstream error timeout;
            proxy_connect_timeout 1s;
            # Longer than the seller's own timeouts (pool 1 s, query 2 s), so the
            # seller answers first with its precise 503 instead of nginx cutting in.
            proxy_read_timeout 15s;
        }
    }

    # Calibration target (A4): answers every buyer call with a canned body and does
    # no other work, so the throughput the buyer achieves against it is the
    # buyer's own ceiling, not the target's.
    server {
        listen 8081;
        default_type application/json;
        location = /buy    { return 409 '{"status":"sold_out","epoch":0}'; }
        location = /reset  { return 200 '{"status":"reset","epoch":0,"total":0,"allocator":"calibration"}'; }
        location = /status { return 200 '{"epoch":0,"total":0,"sold":0,"holders":[],"allocator":"calibration"}'; }
        location = /health { return 200 '{"ok":true}'; }
    }
}

